#include <iostream>
using namespace std;

bool isValid(int grid[9][9], int row, int col, int num) {
    // Check the number in the row
    for (int x = 0; x < 9; x++)
        if (grid[row][x] == num)
            return false;

    // Check the number in the column
    for (int x = 0; x < 9; x++)
        if (grid[x][col] == num)
            return false;

    // Check the number in the box
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j)
            if (grid[i + startRow][j + startCol] == num)
                return false;
    }

    return true;
}

bool solveSudoku(int grid[9][9]) {
    for (int i = 0; i < 9; i++) {
        for (int j = 0; j < 9; j++) {
            if (grid[i][j] == 0) { // empty cell
                for (int num = 1; num <= 9; num++) {
                    if (isValid(grid, i, j, num)) {
                        grid[i][j] = num;
                        if (solveSudoku(grid))
                            return true;
                        else
                            grid[i][j] = 0; // backtrack
                    }
                }
                return false; // no valid number found
            }
        }
    }

    return true; // all cells filled
}

void printBoard(int grid[9][9]) {
    for (int i = 0; i < 9; ++i) {
        if (i % 3 == 0 && i != 0)
            cout << "- - - - - - - - - - - -" << endl;

        for (int j = 0; j < 9; ++j) {
            if ((j % 3 == 0 && j != 0))
                cout << "| ";

            cout << grid[i][j] << " ";
        }

        cout << "|" << endl;
    }
}

int main() {
    int grid[9][9];

    // initialize the board with a given Sudoku puzzle
    grid = {{5,3,0, 0,7,0, 0,0,0},
            {6,0,0, 1,9,5, 0,0,0},
            {0,9,8, 0,0,0, 0,6,0},

            {8,0,0, 0,6,0, 0,0,3},
            {4,0,0, 8,0,3, 0,0,1},
            {7,0,0, 0,2,0, 0,0,6},

            {0,6,0, 0,0,0, 2,8,0},
            {0,0,0, 4,1,9, 0,0,5},
            {0,0,0, 0,8,0, 0,7,9}};

    if (solveSudoku(grid)) {
        printBoard(grid);
    }
    else
        cout << "No solution exists";

    return 0;
}
